WITH d AS (SELECT substr(invoice_date,1,7) m, * FROM invoices WHERE invoice_type='sale' AND invoice_date>='2011-05-01' AND invoice_date<'2011-07-01')
SELECT customer_id, SUM(CASE WHEN m='2011-05' THEN amount ELSE 0 END) may, SUM(CASE WHEN m='2011-06' THEN amount ELSE 0 END) jun, SUM(CASE WHEN m='2011-06' THEN amount ELSE -amount END) diff FROM d GROUP BY 1 ORDER BY diff LIMIT 6;
